use chrono::{DateTime,Duration,NaiveDate,NaiveDateTime,Utc,Datelike};
#[derive(Debug,Clone,serde::Serialize)]pub struct ParsedDate{pub iso:String,pub confidence:f32,pub relative:bool}
pub fn parse(text:&str,now:&str,lang:&str)->Result<ParsedDate,String>{let t=text.trim().to_lowercase();let base=DateTime::parse_from_rfc3339(now).map_err(|e|e.to_string())?.with_timezone(&Utc);let ar=lang.eq_ignore_ascii_case("ar");let (dt,rel)=if t.contains("tomorrow")||t.contains("غدا")||t.contains("غدًا"){(base+Duration::days(1),true)}else if t.contains("today")||t.contains("اليوم"){(base,true)}else if t.contains("yesterday")||t.contains("امس")||t.contains("أمس"){(base-Duration::days(1),true)}else if t.contains("next week")||t.contains("الأسبوع القادم")||t.contains("الاسبوع القادم"){(base+Duration::days(7),true)}else{let date=t.split_whitespace().find_map(|x|NaiveDate::parse_from_str(x,"%Y-%m-%d").ok());if let Some(d)=date{(DateTime::<Utc>::from_naive_utc_and_offset(NaiveDateTime::new(d,base.time()),Utc),false)}else{return Err(if ar{"لم أفهم التاريخ. استخدم YYYY-MM-DD أو اليوم/غداً.".into()}else{"I could not parse the date. Use YYYY-MM-DD or today/tomorrow.".into()})}};Ok(ParsedDate{iso:dt.to_rfc3339(),confidence:if rel{0.98}else{0.95},relative:rel})}
#[cfg(test)]mod tests{use super::*;#[test]fn en_ar_relative(){let n="2026-09-25T10:00:00Z";assert!(parse("tomorrow",n,"en").unwrap().relative);assert!(parse("غدا",n,"ar").unwrap().relative);assert!(parse("2026-10-01",n,"en").is_ok());}}